{"command":"python3 << 'EOF'
import csv

# Check if CSV can be read back correctly
with open('outputs/t11_city_indicator_matrix.csv', 'r') as f:
    reader = csv.reader(f)
    header = next(reader)
    num_cols = len(header)

    issues = []
    for i, row in enumerate(reader):
        if len(row) != num_cols:
            issues.append(f"Row {i+1}: wrong number of columns - expected {num_cols}, got {len(row)}")

    if issues:
        for issue in issues[:5]:
            print(issue)
    else:
        print("CSV is RFC 4180 compliant - all rows have correct number of columns")

    print(f"Header: {header}")
    print(f"First data row: {next(reader, None)}")
EOF"}
